using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
        // Existing documents still use "Discriminator", so preserve it.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF 9 uses only the raw key for "id" (e.g. "1").
        // Existing documents store "Blog|1", so preserve the old format.
        modelBuilder.Entity<Blog>().HasIdProperty(b => b.Id)
            .HasIdJsonPropertyName("id");

        // Breaking change 3: Cosmos DB does not support indexes defined via
        // EF Core's HasIndex. EF 9 now throws instead of silently ignoring.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4: EF 9 defaults to sync-only mode and throws on
        // synchronous calls like ToList() / SaveChanges(). Opt back in if needed.
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CosmosEventId.SyncNotSupported));
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

